import os

MODE = os.environ["WF_MUTANT"]
HIT = os.environ["WF_MUTANT_HIT"]


def _hit():
    with open(HIT, "a") as f:
        f.write(MODE + "\n")


class _NoLock:
    def acquire(self, blocking=True, timeout=-1):
        return True

    def release(self):
        pass

    def locked(self):
        return False

    def __enter__(self):
        return True

    def __exit__(self, *exc):
        return False


def pytest_sessionstart(session):
    from wantrain.fault_tolerance import checkpoint

    if MODE in ("writer-order", "stage-bypass"):

        def invalidate(side):
            _hit()

        checkpoint.invalidate_sidecar = invalidate
    elif MODE == "ship-unlocked":
        from wantrain.worker.agent import WorkerAgent

        lock = _NoLock()

        def get(self):
            _hit()
            return lock

        WorkerAgent._ship_lock = property(get, lambda self, value: None)
    elif MODE == "restore-stale":
        from wantrain.worker import agent

        orig = agent.WorkerAgent._on_restore

        def restore(self, msg, path):
            _hit()
            real = checkpoint.write_sidecar
            had = hasattr(agent, "write_sidecar")
            prev = getattr(agent, "write_sidecar", None)

            def skip(side, step):
                pass

            checkpoint.write_sidecar = skip
            if had:
                agent.write_sidecar = skip
            try:
                return orig(self, msg, path)
            finally:
                checkpoint.write_sidecar = real
                if had:
                    agent.write_sidecar = prev

        agent.WorkerAgent._on_restore = restore
    elif MODE == "resume-trust":
        from wantrain.runtime import stage

        def trust(side, shard_step):
            _hit()

        stage.check_resume_step = trust
        checkpoint.check_resume_step = trust
    else:
        raise RuntimeError("unknown WF_MUTANT " + MODE)
